import React, { useEffect, useState } from "react";
import axios from "axios";

const ApplyInternship = () => {
  const [formData, setFormData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone_number: "",
    education: "",
    internship_offers: "",
    resume: null,
  });

  const handleChange = (e) => {
    const { name, value, files } = e.target;

    if (name === "resume") {
      setFormData({ ...formData, resume: files[0] });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };
  

  useEffect(() => {
    // Fetch internship offers if needed

    axios.get("http://127.0.0.1:8000/VJISS/internship_offers_details")
      .then((response) => {
        setInternships(response.data);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching internship details:", error);
        setLoading(false);
      });
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    data.append("first_name", formData.first_name);
    data.append("last_name", formData.last_name);
    data.append("email", formData.email);
    data.append("phone_number", formData.phone_number);
    data.append("education", formData.education);
    data.append("internship_offers", formData.internship_offers);
    data.append("resume", formData.resume);

    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/VJISS/apply_internship",
        data,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
      alert("Application submitted successfully!");
      console.log(response.data);
    } catch (error) {
      console.error(error);
      alert("Failed to submit application");
    }
  };

  return (
    <form onSubmit={handleSubmit} encType="multipart/form-data">
      <h2>Apply for Internship</h2>

      <input
        type="text"
        name="first_name"
        placeholder="First Name"
        onChange={handleChange}
        required
      />

      <input
        type="text"
        name="last_name"
        placeholder="Last Name"
        onChange={handleChange}
        required
      />

      <input
        type="email"
        name="email"
        placeholder="Email"
        onChange={handleChange}
        required
      />

      <input
        type="text"
        name="phone_number"
        placeholder="Phone Number"
        onChange={handleChange}
        required
      />

      <select name="education" onChange={handleChange} required>
        <option value="">Select Education</option>
        <option value="Diploma">Diploma</option>
        <option value="UG">Under Graduate</option>
        <option value="PG">Post Graduate</option>
        <option value="PhD">PhD</option>
      </select>

      {/* Internship Offer ID */}
      <input
        type="text"
        name="internship_offers"
        placeholder="Internship Offer ID"
        onChange={handleChange}
        required
      />

      <input
        type="file"
        name="resume"
        accept=".pdf,.doc,.docx"
        onChange={handleChange}
        required
      />

      <button type="submit">Apply</button>
    </form>
  );
};

export default ApplyInternship;
